#include "dk1/scene_view.h"
#include "dk1/level_map.h"
#include "dk1/ppu_layout.h"
#include <stdlib.h>
bool dk1_scene_view_clamp(const Dk1SceneMemory*s,Dk1SceneView*v){uint32_t max;if(!s||!v||!v->width||!v->height)return false;if(v->camera_x<s->camera.minimum_x)v->camera_x=s->camera.minimum_x;max=s->camera.maximum_x;if(max>v->width)max-=v->width;else max=s->camera.minimum_x;if(v->camera_x>max)v->camera_x=(uint16_t)max;if(v->camera_y>512u-v->height)v->camera_y=(uint16_t)(512u-v->height);return true;}
bool dk1_scene_render_bg1(const Dk1RomImage*r,const Dk1SceneMemory*s,Dk1SceneView v,Dk1RgbaSurface d){Dk1PpuBgLayout l;size_t first=v.camera_x/32u,pxoff=v.camera_x%32u,cols=(pxoff+v.width+31u)/32u,tw=cols*4u,th=64u;uint16_t*map=NULL;Dk1Rgba8*tmp=NULL;Dk1RgbaSurface ts;size_t y;if(!r||!s||!d.pixels||d.width<v.width||d.height<v.height||!dk1_ppu_bg_layout(&s->ppu,1,&l))return false;map=calloc(tw*th,sizeof(*map));tmp=calloc(tw*8u*th*8u,sizeof(*tmp));if(!map||!tmp){free(map);free(tmp);return false;}if(!dk1_level_map_expand_tiles(r,&s->terrain,first,cols,map,tw,th)){free(map);free(tmp);return false;}ts.pixels=tmp;ts.width=tw*8u;ts.height=th*8u;ts.stride=ts.width;if(!dk1_bg_render_4bpp(&s->vram,&s->cgram,l.character_base_word,map,tw,th,ts)){free(map);free(tmp);return false;}for(y=0;y<v.height;y++){size_t x;for(x=0;x<v.width;x++)d.pixels[y*d.stride+x]=tmp[(v.camera_y+y)*ts.stride+pxoff+x];}free(map);free(tmp);return true;}
